import React, { useEffect, useState } from 'react';
import Aos from 'aos';
import { HashRouter as Router, Routes, Route } from "react-router-dom";
import LoadingBar from 'react-top-loading-bar';
import Navbar from './components/Navbar';
import News from './components/News';
import NoPage from './components/NoPage';

const App = () => {
  const apikey = process.env.REACT_APP_NEWS_API;
  const [progress_val, setProgress_val] = useState(0);
  const [country, setCountry] = useState("us");

  useEffect(() => {
    Aos.init();
  }, []);

  const setProgress = (value) => {
    setProgress_val(value);
  };

  const onCountryChange = (value) => {
    setCountry(value);
  };

  return (
    <>
      <Router>
        <Navbar onCountryChange={onCountryChange}/>
        <LoadingBar color='#f11946' height="2.5px" progress={progress_val} />
        <Routes>
          <Route exact path="/" element={<News setProgress={setProgress}  pagesize={15} country={country} api={apikey} />} />
          <Route exact path="/business" element={<News setProgress={setProgress} key="business" pagesize={15} country={country} category='business' />} />
          <Route exact path="/entertainment" element={<News setProgress={setProgress} key="entertainment" pagesize={15} country={country} category='entertainment' />} />
          <Route exact path="/general" element={<News setProgress={setProgress} key="general" pagesize={15} country={country} category='general' />} />
          <Route exact path="/health" element={<News setProgress={setProgress} key="health" pagesize={15} country={country} category='health' />} />
          <Route exact path="/science" element={<News setProgress={setProgress} key="science" pagesize={15} country={country} category='science' />} />
          <Route exact path="/sports" element={<News setProgress={setProgress} key="sports" pagesize={15} country={country} category='sports' />} />
          <Route exact path="/technology" element={<News setProgress={setProgress} key="technology" pagesize={15} country={country} category='technology' />} />
          <Route exact path="*" element={<NoPage />} />
        </Routes>
      </Router>
    </>
  );
};

export default App;
